-- =====================================================================================================================
--  25-sonra-dogrula-salt-okur.sql — G-25 UYGULANDIKTAN SONRA (SALT OKUR)
--  G-25 — car_yaz YETKİ GENİŞLİĞİ (stok-v2/guvenlik/25-G25-TASARIM.md). ÜRETİLMİŞ DOSYA — elle düzenlenmez:
--  python3 stok-v2/guvenlik/25-uret.py (kaynak: 25-kaynak/yeni.sql + editor/15-duzeltme.sql car_yaz + editor/18-fis-defteri.sql
--  fis_kes / fis_iptal). Gövde özetleri Faz 0.4 envanterinin formülüyle (yorum / boşluk normalize, md5).
-- =====================================================================================================================
with k(sira, kontrol, tamam) as (
  select 1, 'car_yaz G-25 hâlinde', (select md5(btrim(regexp_replace(regexp_replace(p.prosrc, '--[^\n]*', '', 'g'), '\s+', ' ', 'g'))) from pg_proc p where p.oid = to_regprocedure('public.car_yaz(jsonb)')) = '4ee7bfb498c6d729a6ddcf47a420031b'
  union all   select 2, 'fis_kes G-25 hâlinde', (select md5(btrim(regexp_replace(regexp_replace(p.prosrc, '--[^\n]*', '', 'g'), '\s+', ' ', 'g'))) from pg_proc p where p.oid = to_regprocedure('public.fis_kes(jsonb)')) = 'c071d8020d8a22b20765cff7aec77c47'
  union all   select 3, 'fis_iptal G-25 hâlinde', (select md5(btrim(regexp_replace(regexp_replace(p.prosrc, '--[^\n]*', '', 'g'), '\s+', ' ', 'g'))) from pg_proc p where p.oid = to_regprocedure('public.fis_iptal(jsonb)')) = '2ea9f6ce73682303f69f1b8f191e84ab'
  union all select 4, 'yeni fonksiyonların hepsi var (12)', ((to_regprocedure('public.g25_fis_cari_yetki(jsonb)') is not null)::int + (to_regprocedure('public.g25_fis_cari_yetki_tek(jsonb, jsonb, jsonb, jsonb, jsonb)') is not null)::int + (to_regprocedure('public.g25_fis_iptal_yetki(text)') is not null)::int + (to_regprocedure('public.g25_stok_bagi(jsonb, jsonb, jsonb, jsonb)') is not null)::int + (to_regprocedure('public.g25_tanimlar_ucret_koruma()') is not null)::int + (to_regprocedure('public.g25_ucret_ozeti(jsonb)') is not null)::int + (to_regprocedure('public.g25_uretim_bagi(jsonb, jsonb, jsonb, jsonb)') is not null)::int + (to_regprocedure('public.g25_yetki_iste(text[], text, text)') is not null)::int + (to_regprocedure('public.mesai_bildir(jsonb)') is not null)::int + (to_regprocedure('public.mesai_bildirim_iptal(jsonb)') is not null)::int + (to_regprocedure('public.mesai_bildirimleri(jsonb)') is not null)::int + (to_regprocedure('public.mesai_onayla(jsonb)') is not null)::int) = 12
  union all select 5, 'RPC (mesai_*) yalnız authenticated çalıştırır, anon çalıştıramaz', has_function_privilege('authenticated', 'public.mesai_bildir(jsonb)'::regprocedure, 'execute') and not has_function_privilege('anon', 'public.mesai_bildir(jsonb)'::regprocedure, 'execute') and has_function_privilege('authenticated', 'public.mesai_bildirimleri(jsonb)'::regprocedure, 'execute') and not has_function_privilege('anon', 'public.mesai_bildirimleri(jsonb)'::regprocedure, 'execute') and has_function_privilege('authenticated', 'public.mesai_bildirim_iptal(jsonb)'::regprocedure, 'execute') and not has_function_privilege('anon', 'public.mesai_bildirim_iptal(jsonb)'::regprocedure, 'execute') and has_function_privilege('authenticated', 'public.mesai_onayla(jsonb)'::regprocedure, 'execute') and not has_function_privilege('anon', 'public.mesai_onayla(jsonb)'::regprocedure, 'execute')
  union all select 6, 'iç fonksiyonları (g25_*) authenticated / anon çalıştıramaz', not has_function_privilege('authenticated', 'public.g25_fis_cari_yetki(jsonb)'::regprocedure, 'execute') and not has_function_privilege('anon', 'public.g25_fis_cari_yetki(jsonb)'::regprocedure, 'execute') and not has_function_privilege('authenticated', 'public.g25_fis_cari_yetki_tek(jsonb, jsonb, jsonb, jsonb, jsonb)'::regprocedure, 'execute') and not has_function_privilege('anon', 'public.g25_fis_cari_yetki_tek(jsonb, jsonb, jsonb, jsonb, jsonb)'::regprocedure, 'execute') and not has_function_privilege('authenticated', 'public.g25_fis_iptal_yetki(text)'::regprocedure, 'execute') and not has_function_privilege('anon', 'public.g25_fis_iptal_yetki(text)'::regprocedure, 'execute') and not has_function_privilege('authenticated', 'public.g25_stok_bagi(jsonb, jsonb, jsonb, jsonb)'::regprocedure, 'execute') and not has_function_privilege('anon', 'public.g25_stok_bagi(jsonb, jsonb, jsonb, jsonb)'::regprocedure, 'execute') and not has_function_privilege('authenticated', 'public.g25_tanimlar_ucret_koruma()'::regprocedure, 'execute') and not has_function_privilege('anon', 'public.g25_tanimlar_ucret_koruma()'::regprocedure, 'execute') and not has_function_privilege('authenticated', 'public.g25_ucret_ozeti(jsonb)'::regprocedure, 'execute') and not has_function_privilege('anon', 'public.g25_ucret_ozeti(jsonb)'::regprocedure, 'execute') and not has_function_privilege('authenticated', 'public.g25_uretim_bagi(jsonb, jsonb, jsonb, jsonb)'::regprocedure, 'execute') and not has_function_privilege('anon', 'public.g25_uretim_bagi(jsonb, jsonb, jsonb, jsonb)'::regprocedure, 'execute') and not has_function_privilege('authenticated', 'public.g25_yetki_iste(text[], text, text)'::regprocedure, 'execute') and not has_function_privilege('anon', 'public.g25_yetki_iste(text[], text, text)'::regprocedure, 'execute')
  union all select 7, 'mes_bildirim RLS açık, authenticated / anon yetkisi yok', coalesce((select c.relrowsecurity from pg_class c where c.oid = to_regclass('public.mes_bildirim')), false)
       and not has_table_privilege('authenticated', 'public.mes_bildirim', 'select,insert,update,delete') and not has_table_privilege('anon', 'public.mes_bildirim', 'select,insert,update,delete')
  union all select 8, 'tanimlar ücret tetikleyicisi etkin', exists (select 1 from pg_trigger where tgname = 'g25_tanimlar_ucret_koruma' and tgrelid = 'public.tanimlar'::regclass and tgenabled = 'O')
  union all select 9, 'yedek var (3 fonksiyon)', coalesce((select count(*) = 3 from guvenlik.g25_yedek), false)
  union all select 10, 'üç fonksiyonun yetkisi / sahibi yedektekiyle aynı', coalesce((select bool_and(p.proacl::text is not distinct from y.yetki and pg_get_userbyid(p.proowner) = y.sahip)
       from guvenlik.g25_yedek y join pg_proc p on p.oid = ('public.' || y.ad || '(jsonb)')::regprocedure), false)
)
select sira, kontrol, case when tamam then 'tamam' else 'EKSİK' end as durum from k
union all select 99, 'GENEL', case when bool_and(tamam) then 'TAMAM' else 'EKSİK — incele' end from k
order by 1;
